// Using cuBLAS (recommended for standard GEMM)
#include <cublas_v2.h>

cublasHandle_t handle;
cublasCreate(&handle);

// C = alpha * A * B + beta * C
cublasSgemm(handle, CUBLAS_OP_N, CUBLAS_OP_N,
            M, N, K,
            &alpha,
            d_A, lda,
            d_B, ldb,
            &beta,
            d_C, ldc);

// Or using CUTLASS for custom matrix ops
#include <cutlass/gemm/device/gemm.h>

using Gemm = cutlass::gemm::device::Gemm<
    float, cutlass::layout::RowMajor,  // A
    float, cutlass::layout::RowMajor,  // B
    float, cutlass::layout::RowMajor>; // C

memory_coalescing.code_example:
// BAD: Strided access (uncoalesced)
__global__ void bad_kernel(float* A, int stride) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    float val = A[tid * stride];  // Threads access non-consecutive addresses
}

// GOOD: Consecutive access (coalesced)
__global__ void good_kernel(float* A) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    float val = A[tid];  // Threads access consecutive addresses
}

// BETTER: Vectorized access (float4 = 4 elements per transaction)
__global__ void better_kernel(float4* A) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    float4 val = A[tid];  // 128-bit load, perfectly coalesced
}

barrier_stall_detector.code_example:
// WRONG: __syncthreads() in conditional
if (threadIdx.x < 16) {
    shared_data[threadIdx.x] = value;
    __syncthreads();  // BUG: Not all threads reach this!
}

// RIGHT: __syncthreads() outside conditional
if (threadIdx.x < 16) {
    shared_data[threadIdx.x] = value;
}
__syncthreads();  // All threads sync

// BETTER: Use warp-level ops for small data
int warp_sum = __reduce_add_sync(0xFFFFFFFF, value);  // No __syncthreads needed
